from typing import Dict, Anyimport randomfrom datetime import datetimedef search_mock(query_type: str, query_value: str) -> Dict[str, Any]:    now = datetime.utcnow().isoformat()    if query_type.lower() in ("cpf", "cnpj"):        return {            "source": "mock_registry",            "retrieved_at": now,            "identifiers": {query_type: query_value},            "person": {                "name": "João da Silva",                "birthdate": "1985-07-15",                "addresses": [{"street": "Rua Exemplo, 123", "city": "São Paulo", "state": "SP"}],                "phones": ["+5511999999999"],                "emails": ["joao.silva@example.com"]            },            "extra": {"score": random.randint(40, 99), "notes": "Dados provenientes de fonte mock para teste"}        }    if query_type.lower() == "placa":        return {            "source": "mock_veiculos",            "retrieved_at": now,            "plate": query_value,            "vehicle": {                "make": "Volkswagen",                "model": "Gol",                "year": 2012,                "color": "Prata"            },            "owners": [{"name": "João da Silva", "cpf": "000.000.000-00"}]        }    if query_type.lower() == "nome":        return {            "source": "mock_namesearch",            "retrieved_at": now,            "matches": [                {"name": "João da Silva", "cpf": "000.000.000-00", "city": "São Paulo"},                {"name": "João Silva", "cpf": "111.111.111-11", "city": "Rio de Janeiro"}            ]        }    return {        "source": "mock_generic",        "retrieved_at": now,        "data": {"query_type": query_type, "query_value": query_value},        "note": "Nenhum dado real — conector mock"    }